package com.brightloop.portal;
import com.brightloop.catalog.*;import com.brightloop.invoice.*;import com.brightloop.payment.*;import com.brightloop.plan.*;import com.brightloop.subscription.*;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import java.math.BigDecimal;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/portal") @PreAuthorize("hasRole('CUSTOMER')") public class PortalController{
 private final CustomerService customers;private final SubscriptionService subscriptions;private final CustomerRepository customerRepo;private final InvoiceRepository invoices;private final PaymentRepository payments;private final PlanRepository plans;private final BillingService billing;private final PaymentService paymentService;private final com.brightloop.invoice.PdfService pdf;
 public PortalController(CustomerService c,SubscriptionService s,CustomerRepository cr,InvoiceRepository i,PaymentRepository p,PlanRepository pl,BillingService billing,PaymentService paymentService,com.brightloop.invoice.PdfService pdf){customers=c;subscriptions=s;customerRepo=cr;invoices=i;payments=p;plans=pl;this.billing=billing;this.paymentService=paymentService;this.pdf=pdf;}
 @GetMapping("/profile") public CatalogDtos.CustomerResponse profile(Authentication a){return customers.own(a.getName());}
 public record ProfileUpdate(@NotBlank String fullName,String phone,String companyName,String billingAddress,String city,String state,String country,String postalCode){}
 @PatchMapping("/profile") public CatalogDtos.CustomerResponse updateProfile(Authentication a,@Valid @RequestBody ProfileUpdate r){return customers.updateOwn(a.getName(),r.fullName(),r.phone(),r.companyName(),r.billingAddress(),r.city(),r.state(),r.country(),r.postalCode());}
 @GetMapping("/subscriptions") public List<SubscriptionDtos.Response> subscriptions(Authentication a){return subscriptions.own(a.getName());}
 @PostMapping("/subscriptions/{id}/{action}") public SubscriptionDtos.Response subscriptionAction(Authentication a,@PathVariable Long id,@PathVariable String action){return subscriptions.ownAction(a.getName(),id,action);}
 @GetMapping("/invoices") public List<InvoiceDtos.Response> invoices(Authentication a){return billing.listForCustomer(a.getName());}
 @GetMapping("/payments") public List<PaymentService.Response> payments(Authentication a){return paymentService.listForCustomer(a.getName());}
 @GetMapping(value="/invoices/{id}/pdf",produces="application/pdf") public org.springframework.http.ResponseEntity<byte[]> invoicePdf(Authentication a,@PathVariable Long id){var data=pdf.invoice(billing.getForCustomer(id,a.getName()));return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=brightloop-invoice-"+id+".pdf").body(data);}
 @GetMapping(value="/payments/{id}/receipt.pdf",produces="application/pdf") public org.springframework.http.ResponseEntity<byte[]> receiptPdf(Authentication a,@PathVariable Long id){var data=pdf.receipt(paymentService.getForCustomer(id,a.getName()));return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=brightloop-receipt-"+id+".pdf").body(data);}
 public record AvailablePlan(Long id,String name,String productName,String description,BigDecimal price,String frequency){}
 @GetMapping("/plans") public List<AvailablePlan> availablePlans(){return plans.findAll().stream().filter(p->"ACTIVE".equals(p.getStatus())).map(p->new AvailablePlan(p.getId(),p.getName(),p.getProduct().getName(),p.getDescription(),p.getBillingPrice(),p.getBillingFrequency().name())).toList();}
 public record Overview(int activeSubscriptions,int totalSubscriptions,int outstandingInvoices,BigDecimal outstandingAmount,BigDecimal totalPayments){}
 @GetMapping("/overview") public Overview overview(Authentication a){var ss=subscriptions.own(a.getName());var ii=billing.listForCustomer(a.getName());var pp=paymentService.listForCustomer(a.getName());BigDecimal open=ii.stream().map(InvoiceDtos.Response::outstanding).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal collected=pp.stream().map(PaymentService.Response::amount).reduce(BigDecimal.ZERO,BigDecimal::add);return new Overview((int)ss.stream().filter(s->"ACTIVE".equals(s.status())).count(),ss.size(),(int)ii.stream().filter(i->i.outstanding().signum()>0).count(),open,collected);}
 private Customer customer(String email){return customerRepo.findByEmailIgnoreCase(email).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.NOT_FOUND,"Customer profile not found"));}
}
